    LIGHT_KNOWLEDGE_INVALID,
    LIGHT_WORKSPACE_BUSY,
    MAX_BATCHES,
    MAX_DOCUMENT_CHARS,
    MAX_EXPORT_CHARS,
    MAX_EXPORT_CHUNKS,
