def _merge_parent_state(plan: Mapping[str, Any], workspace: Path, step: int) -> tuple[dict[str, Any] | None, str | None] | None:
    if step == 0:
        seed = plan.get("seed_document")
        if seed is None:
            return None, None
        if not _seed_document_shape_ok(seed, plan["paper_id"]):
            return None
