    expected_merge = None
    if plan["batch_count"] == 0:
        if completion.get("merge_sha256") is not None:
            return False
    else:
        last = _final_merge_from_files(workspace, plan)
        if last is None:
            return False
        expected_merge = sha256_canonical(last)
        if completion.get("merge_sha256") != expected_merge:
