        return False
    dest = _records_root(workspace) / record_id
    bundle = _record_bundle_ok(
        workspace,
        dest,
        check_ancestry=False,
        require_completed_job=False,
        bind_job_result=True,
    )
    if bundle is None or bundle["paper_id"] != plan["paper_id"]:
        return False
